"""Render markdown tables from a per-project results JSON. Usage: render_multiproject_tables.py <results.json> <out.md>"""
import json, sys
d = json.load(open(sys.argv[1])); runs = d["runs"]; A = d["per_arm"]; P = d["project"]
def f(x, nd=2): return "-" if x is None else (f"{x:.{nd}f}" if isinstance(x, float) else str(x))
out = [f"## T1 ({P}). Per-run summary (observable artifacts only)", "", "| Run | Arm | Status | Gold rank | Tool calls | API calls | Cost USD | Duration s | Retries | First command | Gold first exposed | Buggy line shown | Calls after gold | Chain path | Route |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in runs: out.append(f"| {r['run_id'].split('/')[1]} | {r['arm']} | {r['status']} | {r['gold_rank']} | {r['tool_call_count']} | {r['api_calls']} | {f(r['cost_usd'],4)} | {round((r['timing']['duration_ms'] or 0)/1000)} | {r['timing']['provider_retry_lines']} | `{(r['info_distance']['first_command'] or '')[:55]}` | {r['gold_first_exposed_step']} | {r['buggy_line_first_shown']} | {r['info_distance']['calls_after_first_gold']} | {r['chain']['chain_path']} | {r['chain']['route']} |")
out += ["", f"## T2 ({P}). Per-arm aggregates (n = 5 each; descriptive only)", "", "| Metric | CONTROL | FIVE-HOP TREATMENT |", "|---|---|---|"]
keys = [("Completed / timeout / startup_timeout", lambda a: f"{a['completed']} / {a['timeout']} / {a.get('startup_timeout', 0)}"), ("Acc@1 / @3 / @5 / @10 (completed runs)", lambda a: " / ".join(f(a[k], 2) for k in ("acc_at_1", "acc_at_3", "acc_at_5", "acc_at_10"))), ("MRR (completed)", lambda a: f(a["mrr"], 3)), ("Acc@1 all-runs (timeout = miss) / MRR all-runs", lambda a: f"{f(a['acc_at_1_all_runs'],2)} / {f(a['mrr_all_runs'],3)}"),
        ("Gold ranks", lambda a: str(a["gold_ranks"])), ("Facade rank per run", lambda a: str(a["facade_rank"])), ("Tool calls (list); mean / median", lambda a: f"{a['tool_calls']}; {a['tool_calls_mean_median'][0]} / {a['tool_calls_mean_median'][1]}"), ("Runs with agent activity (>= 1 tool call)", lambda a: str(a.get('runs_with_agent_activity'))), ("Tool calls mean over completed runs / over runs with agent activity", lambda a: f"{a.get('tool_calls_mean_completed')} / {a.get('tool_calls_mean_active')}"), ("API calls (list); mean", lambda a: f"{a['api_calls']}; {a['api_calls_mean_median'][0]}"), ("Gold first exposed step (list); mean / median", lambda a: f"{a['first_gold_step']}; {a['first_gold_step_mean_median'][0]} / {a['first_gold_step_mean_median'][1]}"),
        ("Buggy line first shown (list)", lambda a: str(a["buggy_line_step"])), ("Tool calls before first gold (list)", lambda a: str(a["calls_to_first_gold"])), ("Calls after gold (list); mean", lambda a: f"{a['calls_after_gold']}; {a['calls_after_gold_mean_median'][0]}"), ("Contract-evidence markers displayed per run", lambda a: str(a["contract_retrieval_count"])), ("Runs with contract evidence before rank / with NEW evidence after gold", lambda a: f"{a['runs_with_contract_evidence_before_rank']} / {a['runs_with_new_contract_evidence_after_gold']}"),
        ("Gold executed/emulated after exposure / javap-jshell runs / recency-heuristic runs", lambda a: f"{a['gold_executed_or_emulated_after_exposure']} / {a['javap_jshell_used']} / {a['recency_heuristic_runs']}"), ("Tests executed per run", lambda a: str(a["tests_executed"])), ("Source files opened per run", lambda a: str(a["source_files_opened"])), ("Unique search queries per run", lambda a: str(a["unique_search_queries"])), ("Novel-vocabulary events / runs", lambda a: f"{a['novel_vocab_events']} / {a['runs_with_novel_vocab']}"), ("build.properties observably used", lambda a: str(a["build_properties_observably_used"])), ("Durations s", lambda a: str(a["durations_s"])), ("Provider retry lines", lambda a: str(a["provider_retry_lines_total"])), ("Cost USD", lambda a: f(a["total_cost_usd"], 4))]
for lab, g in keys: out.append(f"| {lab} | {g(A['CONTROL'])} | {g(A['TREATMENT'])} |")
T = A["TREATMENT"]
if T.get("routes"):
    out += ["", f"## T3 ({P}). Chain completion (TREATMENT)", "", "| Metric | Value |", "|---|---|", f"| Full five-hop sequential traversal (each hop by name after the previous call was shown) | {f(T['full_five_hop_traversal_rate'],2)} |", f"| Full five-hop sequential traversal over runs with agent activity | {f(T.get('full_five_hop_traversal_rate_active'),2)} (n = {T.get('runs_with_agent_activity')}) |", f"| Lexical bypass (strict) over runs with agent activity | {f(T.get('lexical_bypass_rate_active'),2)} |", f"| Repository-wide shortcut over runs with agent activity | {f(T.get('repository_wide_shortcut_rate_active'),2)} |", f"| Buggy line first shown only after hop 4's call line was on screen (runs with activity) | {T.get('buggy_line_after_h4_call_runs')} / {T.get('runs_with_agent_activity')} |", f"| All hops shown in order (any command) | {f(T['all_hops_shown_in_order_rate'],2)} |", f"| Lexical bypass (strict: gold exposed by a search not naming it) | {f(T['lexical_bypass_rate'],2)} |", f"| Repository-wide shortcut | {f(T['repository_wide_shortcut_rate'],2)} |", f"| Direct gold search before hop 4's call | {f(T['direct_gold_search_rate'],2)} |", f"| Abandoned chain | {T['abandoned_chain']} |", f"| Timeout before gold | {T['timeout_before_gold']} |", f"| Runs reaching H1 / H2 / H3 / H4 / H5 | " + " / ".join(str(T['reached_per_hop'][t]) for t in ('H1','H2','H3','H4','H5')) + " |", f"| Skipped hops per run | {T['skipped_hops']} |", f"| Facade ranked first | {T['ranked_facade_first']} |", "| Routes | " + "; ".join(f"{k}: {v}" for k, v in T["routes"].items()) + " |"]
    out += ["", f"## T4 ({P}). Per-run chain flags (TREATMENT)", "", "| Run | reached H1 | H2 | H3 | H4 | H5 | sequential by name | skipped | lexical bypass | repo-wide shortcut | direct gold search | abandoned | timeout before gold | gold exposed by name | buggy line after H4 call |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in runs:
        if r["arm"] != "TREATMENT": continue
        c = r["chain"]; out.append(f"| {r['run_id'].split('/')[1]} | " + " | ".join(str(c['reached'][t]) for t in ('H1','H2','H3','H4','H5')) + f" | {c['followed_all_five_sequentially']} | {','.join(c['skipped_hops']) or 'none'} | {c['lexical_bypass']} | {c['repository_wide_shortcut']} | {c['direct_gold_search']} | {c['abandoned_chain']} | {c['timeout_before_gold']} | {c['gold_exposed_by_name']} | {c.get('buggy_line_shown_after_h4_call')} |")
    out += ["", f"## T5 ({P}). Information distance per run (TREATMENT): first exposure step of each node and increments", "", "| Run | facade | H1 | H2 | H3 | H4 | H5 (gold) | calls->H1 | H1->H2 | H2->H3 | H3->H4 | H4->H5 | calls after gold | contract markers | tests | files opened | unique searches |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in runs:
        if r["arm"] != "TREATMENT": continue
        e = r["chain"]["exposure_steps"]; inc = r["chain"]["increments"]; i = r["info_distance"]
        out.append(f"| {r['run_id'].split('/')[1]} | " + " | ".join(f(e.get(t)) for t in ('facade','H1','H2','H3','H4','H5')) + " | " + " | ".join(f(inc.get(k)) for k in ('incremental_to_H1','incremental_to_H2','incremental_to_H3','incremental_to_H4','incremental_to_H5')) + f" | {f(i['calls_after_first_gold'])} | {i['external_contract_retrieval_count']} | {i['tests_executed_count']} | {len(i['source_files_opened'])} | {i['unique_search_queries']} |")
out += ["", f"## T6 ({P}). Contract-evidence markers: first exposure step (tool OUTPUT), per run", ""]
marks = list(runs[0]["contract_first_shown"].keys()) if runs else []
out += ["| Marker | " + " | ".join(r["run_id"].split("-")[-2][:4] + "/" + r["run_id"].split("/")[1].replace("run-", "") for r in runs) + " |", "|---|" + "---|" * len(runs)]
for m in marks: out.append(f"| `{m}` | " + " | ".join(f(r["contract_first_shown"].get(m)) for r in runs) + " |")
out += ["| gold first exposed | " + " | ".join(f(r["gold_first_exposed_step"]) for r in runs) + " |", "| buggy line first shown | " + " | ".join(f(r["buggy_line_first_shown"]) for r in runs) + " |"]
out += ["", f"## T7 ({P}). Novel search vocabulary events", "", "| Run | Step | Token | Command |", "|---|---|---|---|"]; n = 0
for r in runs:
    for e in r["novel_search_vocabulary"]: n += 1; out.append(f"| {r['run_id'].split('/')[1]} ({r['arm']}) | {e['step']} | `{e['token']}` | `{e['command'][:100]}` |")
if n == 0: out.append("| (none) | - | - | - |")
out += ["", f"## T8 ({P}). Submitted top-5 per run", "", "| Run | Arm | 1 | 2 | 3 | 4 | 5 |", "|---|---|---|---|---|---|---|"]
for r in runs: t = r["top10"] + [""] * 5; out.append(f"| {r['run_id'].split('/')[1]} | {r['arm']} | " + " | ".join(f"`{x.split('.')[-1]}`" if x else "-" for x in t[:5]) + " |")
out += ["", f"## T9 ({P}). Provider request stalls per run (wall clock from the harness start stamp to evaluation.json; per-response timestamps from the trajectory)", "", "| Run | Arm | Status | Responses | Start to first response s | Max gap between responses s | Wall clock s | Stall kind |", "|---|---|---|---|---|---|---|---|"]
for r in runs: t = r["timing"]; out.append(f"| {r['run_id'].split('/')[1]} | {r['arm']} | {r['status']} | {t.get('response_count')} | {f(t.get('start_to_first_response_s'))} | {f(t.get('max_inter_response_gap_s'))} | {f(t.get('wall_clock_s'))} | {t.get('stall_kind')} |")
open(sys.argv[2], "w").write("\n".join(out) + "\n"); print("\n".join(out[:8]))
